def separate_paren_groups(paren_string: str) -> List[str]:
    """
    Separate balanced parenthesis groups from a string, ignoring spaces.
    Each group is a top-level balanced set of parentheses, possibly containing nested groups.
    Returns a list of the groups in the order they appear.
    Raises ValueError if the parentheses are not properly balanced.
    """
    # Remove spaces and keep only parentheses
    cleaned = ''.join(ch for ch in paren_string if ch in '()')
    groups = []
    depth = 0
    start_index = None

    for i, ch in enumerate(cleaned):
        if ch == '(':
            if depth == 0:
                start_index = i
            depth += 1
        elif ch == ')':
            depth -= 1
            if depth < 0:
                raise ValueError("Unbalanced parentheses: too many closing brackets")
            if depth == 0:
                if start_index is None:
                    raise ValueError("Unbalanced parentheses: missing opening bracket")
                groups.append(cleaned[start_index:i+1])
                start_index = None
        else:
            # Should not happen because we filtered, but ignore just in case
            continue

    if depth != 0:
        raise ValueError("Unbalanced parentheses: missing closing brackets")

    return groups

def max_value_on_paths(N: int, grid_values: List[Tuple[int, int, int]]) -> int:
    # Build grid with 1‑based indexing
    grid = [[0] * (N + 1) for _ in range(N + 1)]
    for x, y, val in grid_values:
        if x == 0 and y == 0 and val == 0:
            break
        if 1 <= x <= N and 1 <= y <= N:
            grid[x][y] = val

    if N == 1:
        return grid[1][1]

    INF_NEG = -10**18
    # dp_prev[i1][i2] – best sum when the two walkers are at (i1, j1) and (i2, j2)
    # where j1 = k - i1, j2 = k - i2 for current step k
    dp_prev = [[INF_NEG] * (N + 1) for _ in range(N + 1)]
    dp_prev[1][1] = grid[1][1]

    # k = i + j, starting from 3 up to 2N
    for k in range(3, 2 * N + 1):
        dp_cur = [[INF_NEG] * (N + 1) for _ in range(N + 1)]
        i_min = max(1, k - N)
        i_max = min(N, k - 1)
        for i1 in range(i_min, i_max + 1):
            j1 = k - i1
            if j1 < 1 or j1 > N:
                continue
            for i2 in range(i_min, i_max + 1):
                j2 = k - i2
                if j2 < 1 or j2 > N:
                    continue
                best = INF_NEG
                # consider all four combinations of previous moves
                for di1 in (0, 1):
                    pi1 = i1 - di1
                    if pi1 < 1 or pi1 > N:
                        continue
                    for di2 in (0, 1):
                        pi2 = i2 - di2
                        if pi2 < 1 or pi2 > N:
                            continue
                        val = dp_prev[pi1][pi2]
                        if val > best:
                            best = val
                if best == INF_NEG:
                    continue
                add = grid[i1][j1]
                if i1 != i2 or j1 != j2:
                    add += grid[i2][j2]
                dp_cur[i1][i2] = best + add
        dp_prev = dp_cur

    return dp_prev[N][N]

def optimize_seating(M: int, N: int, K: int, L: int, D: int, chatting_pairs: list) -> (str, str):
    """
    Optimize the placement of aisles in a classroom to minimize the amount of chatting between students.

    Args:
        M (int): The number of rows in the classroom.
        N (int): The number of columns in the classroom.
        K (int): The number of horizontal aisles to add.
        L (int): The number of vertical aisles to add.
        D (int): The number of chatting pairs in the classroom.
        chatting_pairs (list of tuples): A list of tuples, each containing the positions (Xi, Yi) and (Pi, Qi) of a chatting pair.

    Returns:
        (str, str): Two space-separated strings representing the optimal row and column indices for the aisles.
    """
    # Validate inputs
    if M < 2 or N < 2:
        raise ValueError("Classroom must have at least 2 rows and 2 columns.")
    if K < 0 or L < 0:
        raise ValueError("Number of aisles cannot be negative.")
    if K > M - 1 or L > N - 1:
        raise ValueError("Number of aisles exceeds available positions.")
    if D != len(chatting_pairs):
        # Adjust D to actual number of pairs
        D = len(chatting_pairs)

    # Precompute which pairs are separated by each possible aisle
    # Horizontal aisles: between row r and r+1, r in 1..M-1
    horiz_aisles = {}
    for r in range(1, M):
        separated = set()
        for idx, (x1, y1, x2, y2) in enumerate(chatting_pairs):
            if (x1 <= r < x2) or (x2 <= r < x1):
                separated.add(idx)
        horiz_aisles[r] = separated

    # Vertical aisles: between col c and c+1, c in 1..N-1
    vert_aisles = {}
    for c in range(1, N):
        separated = set()
        for idx, (x1, y1, x2, y2) in enumerate(chatting_pairs):
            if (y1 <= c < y2) or (y2 <= c < y1):
                separated.add(idx)
        vert_aisles[c] = separated

    remaining_pairs = set(range(D))
    chosen_h = []
    chosen_v = []

    # Greedy selection of aisles
    while len(chosen_h) < K or len(chosen_v) < L:
        best_aisle = None
        best_type = None  # 'h' or 'v'
        best_benefit = -1

        # Evaluate horizontal candidates
        if len(chosen_h) < K:
            for r, separated in horiz_aisles.items():
                if r in chosen_h:
                    continue
                benefit = len(separated & remaining_pairs)
                if benefit > best_benefit or (benefit == best_benefit and best_type == 'v'):
                    best_benefit = benefit
                    best_aisle = r
                    best_type = 'h'

        # Evaluate vertical candidates
        if len(chosen_v) < L:
            for c, separated in vert_aisles.items():
                if c in chosen_v:
                    continue
                benefit = len(separated & remaining_pairs)
                if benefit > best_benefit or (benefit == best_benefit and best_type == 'h'):
                    best_benefit = benefit
                    best_aisle = c
                    best_type = 'v'

        # If no benefit (all zero), pick smallest available aisle to fill quota
        if best_aisle is None:
            if len(chosen_h) < K:
                # pick smallest unused horizontal
                unused = [r for r in range(1, M) if r not in chosen_h]
                best_aisle = min(unused)
                best_type = 'h'
            else:
                unused = [c for c in range(1, N) if c not in chosen_v]
                best_aisle = min(unused)
                best_type = 'v'

        # Add chosen aisle
        if best_type == 'h':
            chosen_h.append(best_aisle)
            remaining_pairs -= horiz_aisles[best_aisle]
        else:
            chosen_v.append(best_aisle)
            remaining_pairs -= vert_aisles[best_aisle]

    chosen_h.sort()
    chosen_v.sort()

    row_str = ' '.join(map(str, chosen_h)) if chosen_h else ''
    col_str = ' '.join(map(str, chosen_v)) if chosen_v else ''
    return (row_str, col_str)

