def minimum_students_to_leave(heights):
    """
    Calculate the minimum number of students that need to leave to form a choir formation.
    A choir formation is defined such that for some position 'i', the heights of students
    increase from the start to 'i' and decrease from 'i' to the end of the formation.

    Args:
        heights (List[int]): A list of student heights.

    Returns:
        int: The minimum number of students that need to leave.
    """
    # Validate input
    if heights is None:
        raise TypeError("heights must be a list of integers, got None")
    if not isinstance(heights, list):
        raise TypeError(f"heights must be a list, got {type(heights).__name__}")
    for idx, h in enumerate(heights):
        if not isinstance(h, int):
            raise ValueError(f"heights[{idx}] is not an integer: {h!r}")

    n = len(heights)
    if n <= 1:
        return 0

    # Helper: binary search for leftmost insertion point
    def _bisect_left(a, x):
        lo, hi = 0, len(a)
        while lo < hi:
            mid = (lo + hi) // 2
            if a[mid] < x:
                lo = mid + 1
            else:
                hi = mid
        return lo

    # Compute LIS lengths ending at each index
    lis = [0] * n
    tails = []
    for i, h in enumerate(heights):
        pos = _bisect_left(tails, h)
        if pos == len(tails):
            tails.append(h)
        else:
            tails[pos] = h
        lis[i] = pos + 1

    # Compute LIS lengths on reversed list (for decreasing subsequence)
    rev_heights = heights[::-1]
    lis_rev = [0] * n
    tails = []
    for i, h in enumerate(rev_heights):
        pos = _bisect_left(tails, h)
        if pos == len(tails):
            tails.append(h)
        else:
            tails[pos] = h
        lis_rev[i] = pos + 1

    # Map reversed LIS to original indices for decreasing part
    lds = [0] * n
    for i in range(n):
        lds[i] = lis_rev[n - 1 - i]

    # Find maximum bitonic subsequence length
    max_len = 0
    for i in range(n):
        current = lis[i] + lds[i] - 1
        if current > max_len:
            max_len = current

    return n - max_len

def sort_students(student_scores):
    """
    Sorts a list of students based on their scores. The students are sorted primarily by their total score (descending),
    then by their Chinese score (descending), and finally by their student number (ascending) in case of a tie.

    Args:
        student_scores (list): A list of tuples, where each tuple consists of (student_number, total_score, Chinese_score).

    Returns:
        list: A list of tuples sorted according to the above rules.

    Raises:
        TypeError: If the input is not a list of tuples of the correct format.
    """
    if not isinstance(student_scores, list):
        raise TypeError("student_scores must be a list")

    for idx, item in enumerate(student_scores):
        if not isinstance(item, tuple):
            raise TypeError(f"Item at index {idx} is not a tuple")
        if len(item) != 3:
            raise TypeError(f"Tuple at index {idx} does not contain exactly 3 elements")
        student_number, total_score, chinese_score = item
        if not isinstance(student_number, int):
            raise TypeError(f"Student number at index {idx} is not an int")
        if not isinstance(total_score, int):
            raise TypeError(f"Total score at index {idx} is not an int")
        if not isinstance(chinese_score, int):
            raise TypeError(f"Chinese score at index {idx} is not an int")

    # Perform sorting: total_score descending, chinese_score descending, student_number ascending
    return sorted(student_scores, key=lambda x: (-x[1], -x[2], x[0]))
